```python
def compter_voyelles(s):
    voyelles = "aeiouy"
    compte = 0
    for char in s.lower():
        if char in voyelles:
            compte += 1
    return compte
```

```python
def max_liste(l):
    if not l:
        raise ValueError("La liste est vide")
    maximum = l[0]
    for element in l:
        if element > maximum:
            maximum = element
    return maximum
```

```python
def fizzbuzz(n):
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result
```

