def mots_uniques(phrase):
    return set(''.join(c if c.isalnum() else ' ' for c in phrase.lower()).split())
```

```python
def tri_bulles(l):
    n = len(l)
    for i in range(n):
        for j in range(0, n - i - 1):
            if l[j] > l[j + 1]:
                l[j], l[j + 1] = l[j + 1], l[j]
    return l
```

```python
def verifier_ip(s):
    parties = s.split('.')
    if len(parties) != 4:
        return False
    for p in parties:
        if not p.isdigit():
            return False
        if len(p) > 1 and p[0] == '0':
            return False
        if int(p) > 255:
            return False
    return True
```

```python
def freq_chars(s):
    freq = {}
    for char in s:
        freq[char] = freq.get(char, 0) + 1
    return freq
```

```python
def convertir_octets(n):
    if n < 1024:
        return f"{n} Octets"
    elif n < 1024 ** 2:
        return f"{n / 1024:.2f} Ko"
    elif n < 1024 ** 3:
        return f"{n / (1024 ** 2):.2f} Mo"
    else:
        return f"{n / (1024 ** 3):.2f} Go"
```

