```python
def lire_csv(texte):
    resultat = {}
    for ligne in texte.splitlines():
        if ligne:
            parties = ligne.split(',', 1)
            if len(parties) == 2:
                cle = parties[0].strip()
                valeur = parties[1].strip()
                resultat[cle] = valeur
    return resultat
```

```python
def dichotomie(l, x):
    low = 0
    high = len(l) - 1
    while low <= high:
        mid = (low + high) // 2
        if l[mid] == x:
            return mid
        elif l[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return -1
```

